"use client";

import { SignIn } from '@clerk/nextjs'
import { dark } from '@clerk/themes'
import Image from 'next/image'
import Link from 'next/link'
import { useRouter, useSearchParams } from 'next/navigation'
import { useEffect } from 'react'
import { safeDecodeURIComponent } from '../../../lib/auth/authUtils'

export default function Page() {
  const router = useRouter();
  const searchParams = useSearchParams();

  // Handle redirects when the component mounts
  useEffect(() => {
    // Check if we're in a client environment
    if (typeof window !== 'undefined') {
      // Get the current URL
      const currentUrl = window.location.href;
      console.log('Current URL:', currentUrl);

      // Check if we're on the problematic URL pattern
      if (currentUrl.includes('/sign-in?redirect_url=http')) {
        console.log('Detected problematic redirect URL pattern, forcing redirect to dashboard');
        // Force redirect to dashboard
        window.location.href = '/dashboard';
        return;
      }

      // Get the redirect URL from the query parameters
      const redirectUrl = searchParams.get('redirect_url');

      // Log the redirect URL for debugging
      console.log('Sign-in page - redirect URL:', redirectUrl);

      // If we have a redirect URL and we're authenticated, go there directly
      if (redirectUrl) {
        // Check if it's a dashboard URL
        if (redirectUrl.includes('/dashboard')) {
          console.log('Redirecting directly to dashboard');
          router.push('/dashboard');
          return;
        }

        try {
          const decodedUrl = safeDecodeURIComponent(redirectUrl);
          console.log('Decoded redirect URL:', decodedUrl);

          // If it's a relative URL, use it
          if (decodedUrl.startsWith('/')) {
            console.log('Redirecting to relative path:', decodedUrl);
            router.push(decodedUrl);
            return;
          }

          // If it's an absolute URL to our domain, extract the path
          if (decodedUrl.startsWith('http')) {
            try {
              const urlObj = new URL(decodedUrl);
              if (urlObj.hostname === window.location.hostname) {
                console.log('Redirecting to internal path:', urlObj.pathname);
                router.push(urlObj.pathname + urlObj.search + urlObj.hash);
                return;
              }
            } catch (error) {
              console.error('Error parsing URL:', error);
            }
          }
        } catch (error) {
          console.error('Error handling redirect:', error);
        }
      }

      // Add a direct check for the specific URL pattern that's causing issues
      if (window.location.search.includes('redirect_url=http%3A%2F%2Flocalhost%3A3001%2Fdashboard')) {
        console.log('Detected exact problematic URL pattern, forcing redirect to dashboard');
        window.location.href = '/dashboard';
      }
    }
  }, [searchParams, router]);

  return (
    <div className='flex flex-col items-center justify-center min-h-screen p-3'>
      {/* OratorPath Logo */}
      <div className="mb-6">
        <Link href="/" className="flex items-center gap-2 cursor-pointer">
          <Image
            src="/Logo.PNG"
            alt="Logo"
            width={48}
            height={48}
            className="h-12 w-auto filter brightness-125 contrast-125"
            style={{ objectFit: "contain" }}
            priority
          />
          <h1 className="text-2xl font-bold text-white">
            OratorPath
          </h1>
        </Link>
      </div>

      {/* Clerk SignIn Component */}
      <SignIn
        signUpUrl="/sign-up"
        redirectUrl="/dashboard"
        afterSignInUrl="/dashboard"
        appearance={{
          baseTheme: dark,
          elements: {
            logoImage: "hidden",
            logoBox: "hidden",
            headerTitle: "hidden",
            headerSubtitle: "hidden",
            card: "shadow-xl border border-gray-800"
          }
        }}
      />
    </div>
  );
}